const queryClient = new QueryClient();

type Role = 'reporter' | 'moderator' | 'administrator';
type TopCategory = 'Bug' | 'Account' | 'Server';
type BugSubtype = 'Visual' | 'Exploit' | 'Cheat/abuse' | 'Gameplay' | 'Performance' | 'UI/UX' | 'Other';
type AccountSubtype = 'Account recovery' | 'Account scam' | 'Win-trading';
type ServerSubtype = 'Server down' | 'Connection/latency' | 'Matchmaking' | 'Login/authentication' | 'Other';
type ReportSubtype = BugSubtype | AccountSubtype | ServerSubtype;
type ReportStatus = 'Needs review' | 'In progress' | 'Waiting for reporter' | 'Resolved' | 'Closed';
type Priority = 'Urgent' | 'High' | 'Normal' | 'Low';
type StaffMember = { email: string; name: string; initials: string; role: Role; color: string };
type Session = { id: string; displayName: string; email?: string; role: Role };
type Report = {
  id: string; category: TopCategory; subtype: ReportSubtype; title: string; details: string;
  status: ReportStatus; priority: Priority; createdAt: string; ownerId: string; ownerName: string;
  anonymous: boolean; assignee?: string; replies: number; attachment?: string;
  internalNote?: string; duplicateOf?: string; needsReply?: boolean;
};
type Issue = { id: string; title: string; description: string; status: 'Investigating' | 'Monitoring' | 'Resolved'; linkedReports: string[]; progress: number; updatedAt: string };
type ActivityEvent = { id: string; label: string; detail: string; time: string; tone: 'coral' | 'teal' | 'gold' };
type Toast = { id: number; title: string; detail?: string; tone?: 'success' | 'normal' };

