function Avatar({ member, size = 'sm' }: { member?: StaffMember; size?: 'sm' | 'md' }) {
  return <span className={`inline-flex shrink-0 items-center justify-center rounded-full font-bold text-white ${size === 'md' ? 'h-9 w-9 text-[11px]' : 'h-7 w-7 text-[9px]'}`} style={{ background: member?.color ?? '#9da7b4' }} data-testid={`avatar-${member?.email ?? 'unassigned'}`}>{member?.initials ?? '—'}</span>;
}
function CategoryMark({ category, size = 'sm' }: { category: TopCategory; size?: 'sm' | 'md' }) {
  const colors = { Bug: ['#fff0ed', '#ca4e44', AlertCircle], Account: ['#efedfc', '#7468b6', UserRound], Server: ['#e8f6f3', '#247c70', Activity] } as const;
  const [bg, color, Icon] = colors[category];
  return <span className={`inline-flex shrink-0 items-center justify-center rounded-[8px] ${size === 'md' ? 'h-10 w-10' : 'h-7 w-7'}`} style={{ background: bg, color }} data-testid={`category-mark-${category.toLowerCase()}`}><Icon size={size === 'md' ? 17 : 14} /></span>;
}
function Toasts({ toasts, dismiss }: { toasts: Toast[]; dismiss: (id: number) => void }) {
  return <div className="fixed bottom-5 right-5 z-[60] flex w-[min(360px,calc(100vw-32px))] flex-col gap-2" aria-live="polite">{toasts.map((toast) => <button key={toast.id} onClick={() => dismiss(toast.id)} className="flex items-start gap-3 rounded-2xl border border-[#dce4df] bg-[#fffefa] p-4 text-left shadow-[0_12px_35px_rgba(35,53,68,.15)] page-enter" data-testid={`toast-${toast.id}`}><span className="mt-0.5 flex h-6 w-6 items-center justify-center rounded-full bg-[#e8f6f3] text-[#247c70]">{toast.tone === 'success' ? <Check size={14} /> : <Zap size={14} />}</span><span className="min-w-0 flex-1"><strong className="block text-sm font-bold text-[#253044]">{toast.title}</strong><span className="mt-0.5 block text-xs leading-5 text-[#6c7685]">{toast.detail}</span></span><X size={15} className="text-[#98a1ad]" /></button>)}</div>;
}

function AppShell({ children, session, reports, pushToast, signOut }: { children: ReactNode; session: Session; reports: Report[]; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void; signOut: () => void }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const isStaff = session.role !== 'reporter';
  const isAdmin = session.role === 'administrator';
  const nav = isStaff
    ? [{ href: '/', label: 'Overview', icon: LayoutDashboard }, { href: '/inbox', label: 'Moderation inbox', icon: Inbox }, { href: '/my-reports', label: 'My reports', icon: FileText }, { href: '/known-issues', label: 'Known issues', icon: BookOpen }]
    : [{ href: '/', label: 'Home', icon: LayoutDashboard }, { href: '/submit', label: 'Submit report', icon: Plus }, { href: '/my-reports', label: 'My reports', icon: FileText }, { href: '/known-issues', label: 'Known issues', icon: BookOpen }];
  if (isAdmin) nav.push({ href: '/administration', label: 'Administration', icon: Users }, { href: '/settings', label: 'Settings', icon: Settings2 });
  const staffMember = staffFor(session.email);
  return <div className="noise min-h-[100dvh] bg-[#f7f5f0]"><aside className={`fixed inset-y-0 left-0 z-40 flex w-[256px] flex-col bg-[#202f46] px-4 py-5 text-[#f5f3eb] shadow-[8px_0_30px_rgba(25,40,57,.08)] transition-transform duration-300 lg:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between px-2"><Link href="/" onClick={() => setMobileOpen(false)} className="flex items-center gap-3" data-testid="link-brand"><img src="/assets/nulls-logo.png" alt="Nulls" className="h-10 w-10 rounded-[11px]" /><span><strong className="block font-display text-[17px] tracking-[-.03em]">Nulls Report</strong><span className="block text-[10px] uppercase tracking-[.19em] text-[#aab7c8]">Operations room</span></span></Link><button onClick={() => setMobileOpen(false)} className="rounded-lg p-2 text-[#aab7c8] lg:hidden" data-testid="button-close-menu"><X size={18} /></button></div><div className="mt-9 px-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#91a1b5]">{isStaff ? 'Staff workspace' : 'Player workspace'}</div><nav className="mt-2 space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className={`group flex items-center gap-3 rounded-xl px-3 py-3 text-[13px] font-semibold transition ${location === href ? 'bg-[#ef6358] text-white shadow-[0_7px_20px_rgba(239,99,88,.2)]' : 'text-[#c9d2dd] hover:bg-[#2c3b53] hover:text-white'}`} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} strokeWidth={location === href ? 2.4 : 1.8} /><span className="flex-1">{label}</span>{label === 'Moderation inbox' && <span className={`rounded-md px-1.5 py-0.5 font-mono text-[10px] ${location === href ? 'bg-white/20' : 'bg-[#314157] text-[#b7c4d1]'}`}>{reports.filter((r) => r.status === 'Needs review').length}</span>}</Link>)}</nav><div className="mt-auto rounded-2xl border border-[#3b4a60] bg-[#263750] p-3.5"><div className="flex items-center gap-2.5"><span className="h-2.5 w-2.5 rounded-full bg-[#6dd4ad]"></span><span className="text-[11px] font-bold text-[#d9e1e9]">{isStaff ? 'Moderator tools ready' : 'Private reporter view'}</span></div><p className="mt-2 text-[11px] leading-5 text-[#94a5b9]">{isStaff ? 'Only staff can access the moderation inbox and controls.' : 'Only reports submitted from this demo session are shown.'}</p></div><div className="mt-4 flex items-center gap-3 border-t border-[#3b4a60] px-2 pt-4"><Avatar member={staffMember} size="md" /><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{session.displayName}</p><p className="truncate text-[10px] text-[#aab7c8]">{isStaff ? session.role : 'Guest reporter'}</p></div>{isStaff ? <button onClick={signOut} className="text-[#aab7c8] hover:text-white" data-testid="button-sign-out"><LogOut size={16} /></button> : <Link href="/login" className="text-[#aab7c8] hover:text-white" data-testid="link-sign-in"><LogIn size={16} /></Link>}</div></aside>{mobileOpen && <button className="fixed inset-0 z-30 bg-[#152238]/40 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation" data-testid="button-menu-overlay" />}<div className="lg:pl-[256px]"><header className="sticky top-0 z-20 flex h-[74px] items-center justify-between border-b border-[#e6e2d9] bg-[#f7f5f0]/90 px-5 backdrop-blur-md sm:px-8 lg:px-10"><div className="flex items-center gap-3"><button onClick={() => setMobileOpen(true)} className="rounded-xl border border-[#e2ded5] bg-white p-2.5 text-[#445268] lg:hidden" data-testid="button-open-menu"><Menu size={18} /></button><div className="hidden items-center gap-2 text-xs text-[#858e9b] sm:flex"><span className="font-mono text-[11px]">NULLS /</span><span className="font-bold capitalize text-[#2a374b]">{location === '/' ? (isStaff ? 'Overview' : 'Home') : location.slice(1).replaceAll('-', ' ')}</span></div></div><div className="flex items-center gap-2.5"><button onClick={() => pushToast('No new notifications', 'You are caught up on report updates.', 'success')} className="relative rounded-xl p-2.5 text-[#697586] transition hover:bg-white hover:text-[#202f46]" data-testid="button-notifications"><Bell size={18} /></button>{isStaff ? <button onClick={signOut} className="hidden items-center gap-2 rounded-xl border border-[#dedbd3] bg-white px-3 py-2.5 text-xs font-bold text-[#536174] sm:flex" data-testid="button-header-sign-out"><LogOut size={14} /> Sign out</button> : <Link href="/login" className="flex items-center gap-2 rounded-xl bg-[#202f46] px-3.5 py-2.5 text-xs font-bold text-white" data-testid="button-header-sign-in"><LogIn size={14} /> Sign in</Link>}{!isStaff && <Link href="/submit" className="flex items-center gap-2 rounded-xl bg-[#ef6358] px-3.5 py-2.5 text-xs font-bold text-white shadow-[0_5px_15px_rgba(239,99,88,.2)]" data-testid="button-header-submit"><Plus size={15} /> New report</Link>}</div></header><main className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10 lg:py-9">{children}</main></div></div>;
}

function PageHeading({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end page-enter"><div><p className="mb-2 flex items-center gap-2 font-mono text-[10px] font-medium uppercase tracking-[.2em] text-[#ef6358]"><span className="h-1.5 w-1.5 rounded-full bg-[#ef6358]"></span>{eyebrow}</p><h1 className="font-display text-[clamp(28px,4vw,42px)] font-bold leading-[1.05] tracking-[-.045em] text-[#202f46]">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[#6e7887]">{detail}</p></div>{action}</div>;
}
function SectionTitle({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) {
  return <div className="mb-4 flex items-center justify-between gap-3"><div><h2 className="font-display text-[18px] font-bold tracking-[-.025em] text-[#253044]">{title}</h2>{detail && <p className="mt-1 text-xs text-[#87909c]">{detail}</p>}</div>{action}</div>;
}
function MetricCard({ label, value, note, icon: Icon, tone, index }: { label: string; value: string; note: string; icon: typeof Activity; tone: string; index: number }) {
  return <div className={`rounded-2xl border border-[#e6e2d9] bg-white p-5 shadow-[0_3px_10px_rgba(35,53,68,.025)] page-enter stagger-${index}`}><div className="flex items-start justify-between"><span className="text-[11px] font-bold uppercase tracking-[.13em] text-[#89929f]">{label}</span><span className="flex h-8 w-8 items-center justify-center rounded-xl" style={{ color: tone, background: `${tone}14` }}><Icon size={16} /></span></div><div className="mt-5 flex items-end justify-between"><strong className="font-display text-3xl font-bold tracking-[-.06em] text-[#202f46]">{value}</strong><span className="mb-1 text-[10px] font-medium text-[#39824b]">{note}</span></div></div>;
}
function ReportRow({ report, onSelect }: { report: Report; onSelect: (id: string) => void }) {
  const assignee = staffFor(report.assignee);
  return <button onClick={() => onSelect(report.id)} className="group grid w-full grid-cols-[1fr_auto] gap-4 border-b border-[#eeeae2] px-4 py-4 text-left transition hover:bg-[#fffcf5] sm:grid-cols-[minmax(250px,1.5fr)_145px_145px_120px_28px] sm:items-center sm:px-5" data-testid={`row-report-${report.id}`}><div className="flex min-w-0 items-center gap-3"><CategoryMark category={report.category} /><div className="min-w-0"><div className="flex items-center gap-2"><span className="font-mono text-[10px] font-medium text-[#a0a7af]">{report.id}</span><span className={`hidden rounded px-1.5 py-0.5 text-[9px] font-bold sm:inline-block ${priorityStyles[report.priority]}`}>{report.priority}</span></div><p className="mt-1 truncate text-[13px] font-bold text-[#2d394b] group-hover:text-[#ef6358]">{report.title}</p><p className="mt-0.5 truncate text-[11px] text-[#89929f]">{report.subtype} · {report.details}</p></div></div><div className="hidden text-xs sm:block"><span className="block font-medium text-[#536174]">{report.category}</span><span className="mt-1 block text-[10px] text-[#a0a7af]">{report.createdAt}</span></div><div className="hidden sm:block">{assignee ? <span className="flex items-center gap-2"><Avatar member={assignee} /><span className="truncate text-xs font-semibold text-[#596677]">{assignee.name.split(' ')[0]}</span></span> : <span className="text-xs text-[#a0a7af]">Unassigned</span>}</div><span className={`self-start rounded-md px-2 py-1 text-[10px] font-bold sm:self-auto ${statusStyles[report.status]}`}>{report.status}</span><ChevronRight size={16} className="hidden text-[#b4bbc4] transition group-hover:translate-x-0.5 group-hover:text-[#ef6358] sm:block" /></button>;
}

function Overview({ session, reports, issues, onSelectReport, pushToast }: { session: Session; reports: Report[]; issues: Issue[]; onSelectReport: (id: string) => void; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  const isStaff = session.role !== 'reporter';
  const viewReports = isStaff ? reports : reports.filter((report) => report.ownerId === session.id);
  const activity = isStaff ? staffActivity : reporterActivity;
  const needsReply = viewReports.filter((report) => report.needsReply || report.status === 'Waiting for reporter').length;
  const inReview = viewReports.filter((report) => report.status === 'Needs review' || report.status === 'In progress').length;
  const resolved = viewReports.filter((report) => report.status === 'Resolved' || report.status === 'Closed').length;
  const counts = (['Bug', 'Account', 'Server'] as TopCategory[]).map((category) => ({ category, count: viewReports.filter((report) => report.category === category).length }));
  return <div className="page-enter"><PageHeading eyebrow={isStaff ? 'Staff workspace / Overview' : 'Private workspace / Home'} title={isStaff ? `Good morning, ${session.displayName}.` : `Welcome back, ${session.displayName}.`} detail={isStaff ? 'Keep reports moving with clear ownership, practical review, and visible resolution.' : 'Your reports, their status, and the one next step that matters.'} action={<button onClick={() => pushToast('View refreshed', 'Report statuses are current for this demo session.', 'success')} className="flex items-center gap-2 rounded-xl border border-[#dedbd3] bg-white px-3.5 py-2.5 text-xs font-bold text-[#536174] shadow-sm" data-testid="button-refresh-overview"><Activity size={15} /> Refresh view</button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="My reports" value={String(viewReports.filter((report) => isStaff ? report.assignee === session.email : true).length)} note={isStaff ? 'assigned to me' : 'submitted by you'} icon={FileText} tone="#ef6358" index={1} /><MetricCard label="Reports needing a reply" value={String(needsReply)} note="your next response" icon={MessageSquare} tone="#ce9d40" index={2} /><MetricCard label="In review" value={String(inReview)} note="being worked on" icon={ListFilter} tone="#2e9f91" index={3} /><MetricCard label="Resolved" value={String(resolved)} note="closed with care" icon={CheckCircle2} tone="#7468b6" index={4} /></div><div className="mt-8 grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(300px,.75fr)]"><section className="rounded-2xl border border-[#e6e2d9] bg-white p-5 shadow-[0_3px_10px_rgba(35,53,68,.025)]"><SectionTitle title="Recent status timeline" detail={isStaff ? 'Your recent moderation activity' : 'Your reports, from submission to resolution'} /><div className="relative mt-6 space-y-6 pl-2 before:absolute before:bottom-2 before:left-[11px] before:top-2 before:w-px before:bg-[#e7e3dc]">{activity.map((event) => <div key={event.id} className="relative flex gap-4"><span className={`relative z-10 mt-0.5 h-[18px] w-[18px] rounded-full border-4 border-white ${event.tone === 'teal' ? 'bg-[#2e9f91]' : event.tone === 'gold' ? 'bg-[#ce9d40]' : 'bg-[#ef6358]'}`}></span><div className="min-w-0"><p className="text-xs font-bold text-[#455267]">{event.label}</p><p className="mt-1 truncate text-[11px] text-[#89929f]">{event.detail}</p><p className="mt-1 font-mono text-[10px] text-[#a7afb8]">{event.time}</p></div></div>)}</div></section><section className="rounded-2xl border border-[#dceae6] bg-[#f1faf7] p-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#398277]">What happens next</p><h2 className="mt-3 font-display text-[21px] font-bold tracking-[-.03em] text-[#275c56]">{isStaff ? 'Make the next decision clear.' : 'A simple path from report to resolution.'}</h2><div className="mt-5 space-y-4">{(isStaff ? [['01', 'Review the details', 'Check evidence and classify the report.'], ['02', 'Set ownership', 'Assign the next person or ask for context.'], ['03', 'Close the loop', 'Resolve it, mark a duplicate, or keep it moving.']] : [['01', 'We review your report', 'A moderator checks the details and evidence.'], ['02', 'We may ask a question', 'Watch My reports if more context is needed.'], ['03', 'You see the outcome', 'The status stays visible through resolution.']]).map(([num, title, detail]) => <div key={num} className="flex gap-3"><span className="font-mono text-[10px] text-[#2e9f91]">{num}</span><div><strong className="block text-xs text-[#365f5a]">{title}</strong><p className="mt-1 text-[11px] leading-5 text-[#68958d]">{detail}</p></div></div>)}</div>{!isStaff && <Link href="/submit" className="mt-6 flex items-center justify-center gap-2 rounded-xl bg-[#ef6358] py-3 text-xs font-bold text-white" data-testid="link-overview-submit">Submit another report <ArrowRight size={14} /></Link>}</section></div><div className="mt-8 grid gap-5 lg:grid-cols-[1fr_1fr]"><section><SectionTitle title="Nulls Brawl activity" detail="Your report breakdown by category" /><div className="rounded-2xl border border-[#e6e2d9] bg-white p-5">{counts.map(({ category, count }) => <div key={category} className="mb-4 last:mb-0"><div className="mb-2 flex items-center justify-between"><span className="flex items-center gap-2 text-xs font-bold text-[#536174]"><CategoryMark category={category} /> {category}</span><span className="font-mono text-[10px] text-[#89929f]">{count} reports</span></div><div className="h-2 overflow-hidden rounded-full bg-[#f0eee8]"><div className={`h-full rounded-full ${category === 'Bug' ? 'bg-[#ef6358]' : category === 'Account' ? 'bg-[#7468b6]' : 'bg-[#2e9f91]'}`} style={{ width: `${Math.max(8, count * 25)}%` }}></div></div></div>)}</div></section><section><SectionTitle title="Recent reports" detail={isStaff ? 'Reports needing attention' : 'Only your reports are shown'} action={<Link href={isStaff ? '/inbox' : '/my-reports'} className="text-xs font-bold text-[#ef6358]" data-testid="link-overview-reports">{isStaff ? 'Open inbox' : 'View my reports'} <ArrowRight size={13} className="inline" /></Link>} /><div className="overflow-hidden rounded-2xl border border-[#e6e2d9] bg-white">{viewReports.slice(0, 3).map((report) => <ReportRow key={report.id} report={report} onSelect={onSelectReport} />)}</div></section></div></div>;
}

function MyReports({ reports, session, onSelectReport }: { reports: Report[]; session: Session; onSelectReport: (id: string) => void }) {
  const mine = reports.filter((report) => report.ownerId === session.id);
  return <div className="page-enter"><PageHeading eyebrow="Private workspace / Your reports" title="My reports" detail="A private record of the reports submitted from this demo session. No other player reports appear here." action={session.role === 'reporter' ? <Link href="/submit" className="flex items-center gap-2 rounded-xl bg-[#ef6358] px-4 py-2.5 text-xs font-bold text-white" data-testid="button-my-reports-submit"><Plus size={15} /> Submit report</Link> : undefined} /><div className="mb-5 rounded-2xl border border-[#dceae6] bg-[#f1faf7] p-4 text-xs text-[#518b83]"><Shield size={15} className="mr-2 inline" /> Access boundary: this view is limited to reports owned by <strong>{session.displayName}</strong>.</div><div className="overflow-hidden rounded-2xl border border-[#e6e2d9] bg-white">{mine.length ? mine.map((report) => <ReportRow key={report.id} report={report} onSelect={onSelectReport} />) : <EmptyState icon={FileText} title="No reports from this session" detail="Reports submitted from this account will appear here with their current status." action={session.role === 'reporter' ? <Link href="/submit" className="text-xs font-bold text-[#ef6358]" data-testid="link-empty-submit">Submit your first report</Link> : undefined} />}</div></div>;
}

function InboxPage({ reports, setReports, issues, pushToast, onSelectReport, selectedId }: { reports: Report[]; setReports: (reports: Report[]) => void; issues: Issue[]; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void; onSelectReport: (id: string) => void; selectedId?: string }) {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState<'All' | TopCategory>('All'); const [group, setGroup] = useState<'All' | ReportStatus>('All');
  const filtered = useMemo(() => reports.filter((report) => (category === 'All' || report.category === category) && (group === 'All' || report.status === group) && `${report.id} ${report.title} ${report.details} ${report.ownerName}`.toLowerCase().includes(query.toLowerCase())), [reports, query, category, group]);
  const update = (id: string, patch: Partial<Report>, message: string) => { setReports(reports.map((report) => report.id === id ? { ...report, ...patch } : report)); pushToast(message, `${id} was updated in the moderation inbox.`, 'success'); };
  const selected = reports.find((report) => report.id === selectedId);
  const groups: ReportStatus[] = ['Needs review', 'In progress', 'Waiting for reporter', 'Resolved'];
  return <div className="page-enter"><PageHeading eyebrow="Staff workspace / Moderation" title="Moderation inbox" detail="An actionable inbox for review, ownership, follow-up, and resolution across Nulls Brawl reports." action={<button onClick={() => pushToast('Inbox refreshed', 'The moderation view is current for this demo.', 'success')} className="flex items-center gap-2 rounded-xl border border-[#dedbd3] bg-white px-3.5 py-2.5 text-xs font-bold text-[#536174]" data-testid="button-refresh-inbox"><Activity size={15} /> Refresh inbox</button>} /><div className="mb-5 grid gap-3 sm:grid-cols-4">{groups.map((status) => <button key={status} onClick={() => setGroup(group === status ? 'All' : status)} className={`rounded-2xl border p-4 text-left transition ${group === status ? 'border-[#ef6358] bg-[#fff0ed]' : 'border-[#e6e2d9] bg-white hover:border-[#d4cdc0]'}`} data-testid={`button-inbox-group-${status.toLowerCase().replaceAll(' ', '-')}`}><span className="block text-[10px] font-bold uppercase tracking-[.12em] text-[#89929f]">{status}</span><strong className="mt-3 block font-display text-2xl tracking-[-.05em] text-[#202f46]">{reports.filter((report) => report.status === status).length}</strong></button>)}</div><div className="mb-4 flex flex-col gap-3 rounded-2xl border border-[#e6e2d9] bg-white p-3 sm:flex-row"><label className="relative min-w-0 flex-1"><Search size={16} className="absolute left-3 top-3 text-[#9ba3ad]" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search report IDs, titles, or reporter names" className="h-10 w-full rounded-xl bg-[#f7f5f0] pl-9 pr-3 text-xs outline-none focus:ring-2 focus:ring-[#ef6358]" data-testid="input-inbox-search" /></label><div className="flex gap-2"><select value={category} onChange={(e) => setCategory(e.target.value as typeof category)} className="h-10 rounded-xl border border-[#e6e2d9] bg-white px-3 text-xs font-semibold text-[#596677] outline-none focus:border-[#ef6358]" data-testid="select-inbox-category"><option>All</option><option>Bug</option><option>Account</option><option>Server</option></select><button onClick={() => { setQuery(''); setCategory('All'); setGroup('All'); }} className="flex h-10 items-center gap-2 rounded-xl border border-[#e6e2d9] px-3 text-xs font-bold text-[#697586]" data-testid="button-clear-inbox"><Filter size={15} /> Clear</button></div></div><div className="overflow-hidden rounded-2xl border border-[#e6e2d9] bg-white"><div className="flex items-center justify-between border-b border-[#eeeae2] px-4 py-3.5 sm:px-5"><span className="text-xs font-bold text-[#455267]">{filtered.length} reports shown</span><span className="font-mono text-[10px] text-[#a0a7af]">grouped by status</span></div>{filtered.length ? filtered.map((report) => <ReportRow key={report.id} report={report} onSelect={onSelectReport} />) : <EmptyState icon={Inbox} title="Nothing in this view" detail="Change the status group or search for a different report." action={<button onClick={() => { setQuery(''); setCategory('All'); setGroup('All'); }} className="text-xs font-bold text-[#ef6358]" data-testid="button-reset-inbox">Reset inbox view</button>} />}</div>{selected && <StaffReportDetail report={selected} issues={issues} onClose={() => onSelectReport('')} update={update} pushToast={pushToast} />}</div>;
}

function StepTitle({ kicker, title, detail }: { kicker: string; title: string; detail: string }) {
  return <div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#ef6358]">{kicker}</p><h2 className="mt-2 font-display text-[25px] font-bold tracking-[-.04em] text-[#202f46]">{title}</h2><p className="mt-2 text-sm leading-6 text-[#7b8693]">{detail}</p></div>;
}

function StaffReportDetail({ report, issues, onClose, update, pushToast }: { report: Report; issues: Issue[]; onClose: () => void; update: (id: string, patch: Partial<Report>, message: string) => void; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  const [note, setNote] = useState(report.internalNote ?? ''); const assignee = staffFor(report.assignee);
  return <div className="fixed inset-0 z-30 flex justify-end bg-[#152238]/25 backdrop-blur-[2px]" onClick={onClose}><aside className="h-full w-full max-w-[520px] overflow-y-auto bg-[#fffefa] p-5 shadow-[-12px_0_40px_rgba(25,40,57,.15)] sm:p-7" onClick={(e) => e.stopPropagation()}><div className="flex items-center justify-between"><span className="flex items-center gap-2 font-mono text-[11px] font-medium text-[#89929f]"><CategoryMark category={report.category} /> {report.id}</span><button onClick={onClose} className="rounded-xl p-2 text-[#89929f] hover:bg-[#f1eee7]" data-testid="button-close-staff-detail"><X size={19} /></button></div><div className="mt-7 flex items-start justify-between gap-4"><div><span className={`rounded-md px-2 py-1 text-[10px] font-bold ${statusStyles[report.status]}`}>{report.status}</span><h2 className="mt-4 font-display text-[25px] font-bold leading-tight tracking-[-.04em] text-[#202f46]">{report.title}</h2></div><span className={`flex items-center gap-1.5 pt-1 text-[10px] font-bold ${priorityStyles[report.priority]}`}><Flag size={13} fill="currentColor" />{report.priority}</span></div><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-xl bg-[#f7f5f0] p-3"><span className="block text-[10px] uppercase tracking-wider text-[#9ba3ad]">Reporter</span><strong className="mt-1 block text-xs text-[#46546a]">{report.anonymous ? 'Anonymous reporter' : report.ownerName}</strong></div><div className="rounded-xl bg-[#f7f5f0] p-3"><span className="block text-[10px] uppercase tracking-wider text-[#9ba3ad]">Category</span><strong className="mt-1 block text-xs text-[#46546a]">{report.category} · {report.subtype}</strong></div></div><p className="mt-5 text-sm leading-6 text-[#697586]">{report.details}</p>{report.attachment && <div className="mt-4 flex items-center gap-3 rounded-xl border border-dashed border-[#d7d2c8] bg-[#fbfaf7] p-3"><Paperclip size={16} className="text-[#7b8693]" /><span className="text-xs font-bold text-[#536174]">{report.attachment}</span><button onClick={() => pushToast('Evidence preview', 'Attachment preview is represented in this local demo.')} className="ml-auto text-[10px] font-bold text-[#ef6358]" data-testid="button-preview-evidence">Preview</button></div>}<div className="mt-6 border-t border-[#eeeae2] pt-5"><label className="mb-2 block text-[10px] font-bold uppercase tracking-[.14em] text-[#8e98a5]">Status</label><div className="flex flex-wrap gap-2">{(['Needs review', 'In progress', 'Waiting for reporter', 'Resolved', 'Closed'] as ReportStatus[]).map((value) => <button key={value} onClick={() => update(report.id, { status: value, needsReply: value === 'Waiting for reporter' }, `Marked ${value.toLowerCase()}`)} className={`rounded-lg border px-2.5 py-2 text-[10px] font-bold ${report.status === value ? 'border-[#202f46] bg-[#202f46] text-white' : 'border-[#e4e0d7] text-[#6a7584] hover:border-[#ef6358]'}`} data-testid={`button-staff-status-${value.toLowerCase().replaceAll(' ', '-')}`}>{value}</button>)}</div></div><div className="mt-6 border-t border-[#eeeae2] pt-5"><div className="mb-3 flex items-center justify-between"><label className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8e98a5]">Assign report</label>{assignee && <button onClick={() => update(report.id, { assignee: undefined }, 'Report unassigned')} className="text-[10px] font-bold text-[#a0a7af]" data-testid="button-staff-unassign">Unassign</button>}</div><div className="flex flex-wrap gap-2">{Object.values(STAFF_DIRECTORY).map((member) => <button key={member.email} onClick={() => update(report.id, { assignee: member.email }, `Assigned to ${member.name}`)} className={`flex items-center gap-2 rounded-xl border px-2.5 py-2 ${report.assignee === member.email ? 'border-[#2e9f91] bg-[#e8f6f3]' : 'border-[#e4e0d7]'}`} data-testid={`button-staff-assign-${member.initials}`}><Avatar member={member} /><span className="text-[11px] font-bold text-[#566276]">{member.name}</span></button>)}</div></div><div className="mt-6 border-t border-[#eeeae2] pt-5"><label className="mb-2 block text-[10px] font-bold uppercase tracking-[.14em] text-[#8e98a5]">Priority</label><div className="flex gap-2">{(['Urgent', 'High', 'Normal', 'Low'] as Priority[]).map((value) => <button key={value} onClick={() => update(report.id, { priority: value }, `Priority set to ${value.toLowerCase()}`)} className={`rounded-lg border px-2.5 py-2 text-[10px] font-bold ${report.priority === value ? 'border-[#202f46] bg-[#f2f0ea]' : 'border-[#e4e0d7] text-[#798392]'}`} data-testid={`button-staff-priority-${value.toLowerCase()}`}>{value}</button>)}</div></div><div className="mt-6 border-t border-[#eeeae2] pt-5"><label className="mb-2 block text-[10px] font-bold uppercase tracking-[.14em] text-[#8e98a5]">Internal note</label><textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Only staff can see this note." rows={3} className="w-full resize-none rounded-xl border border-[#e1ded6] bg-[#fbfaf7] p-3 text-xs leading-5 outline-none focus:border-[#2e9f91]" data-testid="textarea-internal-note" /><button onClick={() => update(report.id, { internalNote: note }, 'Internal note saved')} className="mt-2 rounded-lg bg-[#202f46] px-3 py-2 text-[10px] font-bold text-white" data-testid="button-save-internal-note">Save note</button></div><button onClick={() => update(report.id, { duplicateOf: report.duplicateOf ?? 'NB-1045', status: 'Closed' }, 'Report marked as duplicate')} className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl border border-[#efc9c4] py-3 text-xs font-bold text-[#ca4e44] hover:bg-[#fff0ed]" data-testid="button-mark-duplicate"><Copy size={14} /> Mark duplicate</button><div className="mt-6 rounded-2xl border border-[#dceae6] bg-[#f1faf7] p-4"><div className="flex items-start gap-3"><Link2 size={17} className="mt-0.5 text-[#2e9f91]" /><div><span className="text-[10px] font-bold uppercase tracking-wider text-[#398277]">Verified issue links</span><p className="mt-1 text-xs leading-5 text-[#62928b]">{issues.filter((issue) => issue.linkedReports.includes(report.id)).length ? 'This report contributes to a verified Nulls Brawl issue.' : 'No verified issue link yet. Review recurrence before linking.'}</p></div></div></div><div className="mt-6 flex items-center justify-between border-t border-[#eeeae2] pt-5 text-[11px] text-[#99a1ac]"><span className="flex items-center gap-1.5"><MessageSquare size={14} /> {report.replies} replies</span><span>{report.id}</span></div></aside></div>;
}

function Submit({ session, onSubmit, pushToast }: { session: Session; onSubmit: (report: Report) => void; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  const [step, setStep] = useState(1); const [category, setCategory] = useState<TopCategory | ''>(''); const [subtype, setSubtype] = useState<ReportSubtype | ''>(''); const [title, setTitle] = useState(''); const [details, setDetails] = useState(''); const [anonymous, setAnonymous] = useState(false); const [done, setDone] = useState(false); const [submittedId, setSubmittedId] = useState('');
  const next = () => { if (step === 1 && category) setStep(2); else if (step === 2 && subtype) setStep(3); else if (step === 3 && title.trim() && details.trim()) setStep(4); };
  const submit = () => { const id = `NB-${1051 + Math.floor(Math.random() * 40)}`; onSubmit({ id, category: category as TopCategory, subtype: subtype as ReportSubtype, title: title.trim(), details: details.trim(), status: 'Needs review', priority: 'Normal', createdAt: 'Just now', ownerId: session.id, ownerName: session.displayName, anonymous, replies: 0 }); setSubmittedId(id); setDone(true); pushToast('Report submitted', `${id} is now in My reports.`, 'success'); };
  if (done) return <div className="mx-auto max-w-2xl page-enter"><div className="rounded-3xl border border-[#dceae6] bg-[#f1faf7] px-6 py-14 text-center sm:px-16"><span className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#2e9f91] text-white shadow-[0_8px_20px_rgba(46,159,145,.2)]"><Check size={30} /></span><p className="mt-7 font-mono text-[10px] uppercase tracking-[.2em] text-[#398277]">Report submitted</p><h1 className="mt-3 font-display text-3xl font-bold tracking-[-.045em] text-[#202f46]">We have your report.</h1><p className="mx-auto mt-4 max-w-md text-sm leading-6 text-[#61847f]">Your report ID is <strong className="font-mono text-[#275c56]">{submittedId}</strong>. Keep it handy while the Nulls team reviews the details.</p><div className="mt-8 flex flex-col justify-center gap-2 sm:flex-row"><Link href="/my-reports" className="rounded-xl bg-[#202f46] px-5 py-3 text-xs font-bold text-white" data-testid="link-private-my-reports">Go to My reports</Link><button onClick={() => { setDone(false); setStep(1); setCategory(''); setSubtype(''); setTitle(''); setDetails(''); }} className="rounded-xl border border-[#c9d8d5] px-5 py-3 text-xs font-bold text-[#247c70]" data-testid="button-submit-another">Submit another</button></div></div></div>;
  return <div className="mx-auto max-w-[930px] page-enter"><PageHeading eyebrow="Player support / Nulls Brawl" title="Tell us what happened." detail="A short, specific report gives the moderation team a clear place to start." /><div className="grid gap-7 lg:grid-cols-[220px_1fr]"><div className="rounded-2xl border border-[#e6e2d9] bg-white p-4 lg:h-fit"><p className="mb-4 px-2 font-mono text-[10px] uppercase tracking-[.18em] text-[#9aa2ac]">Your report</p>{['Choose a category', 'Choose a subtype', 'Add details', 'Review & send'].map((item, i) => <div key={item} className={`relative flex items-center gap-3 rounded-xl px-3 py-3 ${step === i + 1 ? 'bg-[#fff0ed]' : ''}`}><span className={`flex h-7 w-7 items-center justify-center rounded-full text-[10px] font-bold ${step > i + 1 ? 'bg-[#2e9f91] text-white' : step === i + 1 ? 'bg-[#ef6358] text-white' : 'bg-[#f0eee8] text-[#9ba3ad]'}`}>{step > i + 1 ? <Check size={13} /> : `0${i + 1}`}</span><span className={`text-xs font-bold ${step === i + 1 ? 'text-[#ca4e44]' : 'text-[#7c8795]'}`}>{item}</span></div>)}</div><div className="rounded-2xl border border-[#e6e2d9] bg-white p-5 sm:p-8">{step === 1 && <div><StepTitle kicker="Step 01" title="What needs attention?" detail="Start with one of the three report categories used by the Nulls Brawl team." /><div className="mt-7 grid gap-3 sm:grid-cols-3">{(['Bug', 'Account', 'Server'] as TopCategory[]).map((item) => <button key={item} onClick={() => { setCategory(item); setSubtype(''); }} className={`flex flex-col items-start gap-4 rounded-2xl border p-5 text-left transition ${category === item ? 'border-[#ef6358] bg-[#fff4f1] shadow-[0_4px_14px_rgba(239,99,88,.1)]' : 'border-[#e7e3dc] hover:border-[#cfc8bb]'}`} data-testid={`button-select-category-${item.toLowerCase()}`}><CategoryMark category={item} size="md" /><span className="flex w-full items-center justify-between text-sm font-bold text-[#344258]">{item}{category === item && <CheckCircle2 size={17} className="text-[#ef6358]" />}</span><span className="text-[10px] leading-4 text-[#929ba6]">{item === 'Bug' ? 'Something in play is not working as expected.' : item === 'Account' ? 'A player or account concern that needs review.' : 'The game connection or service is unavailable.'}</span></button>)}</div></div>}{step === 2 && <div><StepTitle kicker="Step 02" title="Choose the closest subtype." detail="This helps the team put your report in the right hands without adding extra steps." /><div className="mt-7 grid gap-2 sm:grid-cols-2">{category && categorySubtypes[category].map((item) => <button key={item} onClick={() => setSubtype(item)} className={`flex items-center gap-3 rounded-xl border p-4 text-left transition ${subtype === item ? 'border-[#2e9f91] bg-[#f1faf7]' : 'border-[#e7e3dc] hover:border-[#cfc8bb]'}`} data-testid={`button-select-subtype-${item.toLowerCase().replaceAll('/', '-').replaceAll(' ', '-')}`}><span className={`flex h-8 w-8 items-center justify-center rounded-lg ${subtype === item ? 'bg-[#2e9f91] text-white' : 'bg-[#f2f0ea] text-[#7c8795]'}`}><Tag size={16} /></span><span className="text-xs font-bold text-[#344258]">{item}</span>{subtype === item && <Check size={15} className="ml-auto text-[#2e9f91]" />}</button>)}</div></div>}{step === 3 && <div><StepTitle kicker="Step 03" title="Add the useful details." detail="Tell us what you expected, what happened, and how to see it again. Evidence is welcome." /><div className="mt-7 space-y-5"><label className="block text-xs font-bold text-[#536174]">Short title<input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Battle freezes after first card" className="mt-2 h-11 w-full rounded-xl border border-[#e1ded6] bg-[#fbfaf7] px-3 text-sm outline-none focus:border-[#ef6358] focus:ring-2 focus:ring-[#ef6358]/10" data-testid="input-report-title" /></label><label className="block text-xs font-bold text-[#536174]">What happened?<textarea value={details} onChange={(e) => setDetails(e.target.value)} placeholder="Include steps to reproduce, device or version details, and anything else the team should see." rows={6} className="mt-2 w-full resize-none rounded-xl border border-[#e1ded6] bg-[#fbfaf7] p-3 text-sm leading-6 outline-none focus:border-[#ef6358] focus:ring-2 focus:ring-[#ef6358]/10" data-testid="textarea-report-details" /></label><div className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#d7d2c8] bg-[#fbfaf7] p-4" onClick={() => pushToast('Evidence ready', 'File upload is represented as a local demo placeholder.')}><span className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#f0eee8] text-[#7b8693]"><Paperclip size={17} /></span><span className="flex-1"><strong className="block text-xs text-[#536174]">Add evidence</strong><span className="mt-1 block text-[10px] text-[#929ba6]">Screenshot or clip placeholder · up to 10 MB</span></span><button className="rounded-lg border border-[#dedbd3] px-2.5 py-1.5 text-[10px] font-bold text-[#687586]" data-testid="button-add-evidence">Browse</button></div><button onClick={() => setAnonymous(!anonymous)} className="flex items-center gap-3 text-left" data-testid="button-toggle-anonymous"><span className={`relative h-5 w-9 rounded-full transition ${anonymous ? 'bg-[#2e9f91]' : 'bg-[#d5d9d8]'}`}><span className={`absolute top-1 h-3 w-3 rounded-full bg-white transition ${anonymous ? 'left-5' : 'left-1'}`}></span></span><span><strong className="block text-xs font-bold text-[#536174]">Send anonymously</strong><span className="block text-[10px] text-[#929ba6]">Your display name will not be shown to moderators</span></span></button></div></div>}{step === 4 && <div><StepTitle kicker="Step 04" title="Ready to send?" detail="Give the details one last look. You can add context later if the team asks." /><div className="mt-7 rounded-2xl bg-[#f7f5f0] p-5"><div className="flex items-center gap-3"><CategoryMark category={category as TopCategory} size="md" /><div><span className="font-mono text-[10px] text-[#9ca4ad]">{category} · {subtype}</span><h3 className="mt-1 text-sm font-bold text-[#2d3a4d]">{title}</h3></div></div><p className="mt-5 border-t border-[#e6e2d9] pt-4 text-xs leading-6 text-[#667285]">{details}</p></div><div className="mt-5 flex items-center gap-3 rounded-xl bg-[#f1faf7] p-4 text-xs text-[#518b83]"><Shield size={17} /><span>This private report will appear in <strong>My reports</strong> as <strong>{anonymous ? 'anonymous' : session.displayName}</strong>.</span></div></div>}<div className="mt-8 flex items-center justify-between border-t border-[#eeeae2] pt-5">{step > 1 ? <button onClick={() => setStep(step - 1)} className="flex items-center gap-1 text-xs font-bold text-[#7b8693]" data-testid="button-report-back"><ChevronLeft size={15} /> Back</button> : <span />}{step < 4 ? <button onClick={next} disabled={(step === 1 && !category) || (step === 2 && !subtype) || (step === 3 && (!title.trim() || !details.trim()))} className="flex items-center gap-2 rounded-xl bg-[#ef6358] px-5 py-3 text-xs font-bold text-white disabled:cursor-not-allowed disabled:opacity-40" data-testid="button-report-next">Continue <ArrowRight size={15} /></button> : <button onClick={submit} className="flex items-center gap-2 rounded-xl bg-[#2e9f91] px-5 py-3 text-xs font-bold text-white" data-testid="button-submit-report"><Check size={15} /> Send report</button>}</div></div></div></div>;
}

function KnownIssues({ issues, pushToast }: { issues: Issue[]; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  return <div className="page-enter"><PageHeading eyebrow="Player-facing / Transparency" title="Known issues" detail="A clear look at what the Nulls Brawl team is tracking, what’s moving, and what’s already fixed." action={<button onClick={() => pushToast('Link copied', 'The public known issues link is ready to share.', 'success')} className="flex items-center gap-2 rounded-xl border border-[#dedbd3] bg-white px-3.5 py-2.5 text-xs font-bold text-[#536174]" data-testid="button-copy-known-issues"><Copy size={14} /> Copy link</button>} /><div className="rounded-3xl bg-[#202f46] px-6 py-8 text-white sm:px-9"><div className="max-w-2xl"><span className="inline-flex items-center gap-2 rounded-full bg-[#2e9f91]/20 px-3 py-1.5 text-[10px] font-bold text-[#7ed7c0]"><CheckCircle2 size={13} /> Updated with the latest review</span><h2 className="mt-5 font-display text-3xl font-bold tracking-[-.045em]">What we’re working through.</h2><p className="mt-3 text-sm leading-6 text-[#aab8c8]">When several reports describe the same issue, the team keeps one clear note here until the resolution is ready.</p></div></div><div className="mt-8 grid gap-8 lg:grid-cols-[1fr_280px]"><div><SectionTitle title="Current investigations" detail="The team is actively reviewing these Nulls Brawl issues." /><div className="space-y-3">{issues.filter((issue) => issue.status !== 'Resolved').map((issue) => <div key={issue.id} className="rounded-2xl border border-[#e6e2d9] bg-white p-5"><div className="flex gap-3"><CategoryMark category="Bug" /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-display text-[17px] font-bold tracking-[-.02em] text-[#29374c]">{issue.title}</h3><span className="rounded-md bg-[#e8f6f3] px-2 py-1 text-[10px] font-bold text-[#247c70]">{issue.status}</span></div><p className="mt-2 text-xs leading-5 text-[#7e8996]">{issue.description}</p><p className="mt-4 text-[10px] text-[#a0a7af]">Last updated {issue.updatedAt} · {issue.linkedReports.length} reports connected</p></div></div></div>)}</div><div className="mt-8"><SectionTitle title="Recently resolved" detail="Completed work from the Nulls Brawl team." /><div className="space-y-3">{issues.filter((issue) => issue.status === 'Resolved').map((issue) => <div key={issue.id} className="flex items-center gap-3 rounded-2xl border border-[#e6e2d9] bg-white p-4"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#e9f5eb] text-[#39824b]"><Check size={15} /></span><div className="min-w-0"><h3 className="truncate text-xs font-bold text-[#445166]">{issue.title}</h3><p className="mt-1 text-[10px] text-[#9aa2ac]">Resolved {issue.updatedAt}</p></div></div>)}</div></div></div><aside className="h-fit rounded-2xl border border-[#e6e2d9] bg-[#fffefa] p-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#9aa2ac]">How this works</p><div className="mt-5 space-y-5">{[['01', 'You report it', 'Your details give the team a place to start.'], ['02', 'We review the pattern', 'Repeated reports can become one verified issue.'], ['03', 'The resolution becomes visible', 'Updates stay here until the issue is resolved.']].map(([num, title, detail]) => <div key={num} className="flex gap-3"><span className="font-mono text-[10px] text-[#ef6358]">{num}</span><div><strong className="block text-xs text-[#46546a]">{title}</strong><p className="mt-1 text-[11px] leading-5 text-[#89929f]">{detail}</p></div></div>)}</div><Link href="/submit" className="mt-6 flex items-center justify-center gap-2 rounded-xl bg-[#ef6358] py-3 text-xs font-bold text-white" data-testid="link-known-submit">Submit a report <ArrowRight size={14} /></Link></aside></div></div>;
}

function Administration() {
  return <div className="page-enter"><PageHeading eyebrow="Administrator / Access control" title="Administration" detail="Manage who can review reports and which permissions are available in this local demo." /><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-[#e6e2d9] bg-white p-5 sm:p-6"><SectionTitle title="Staff role directory" detail="These identities come from the source-configured STAFF_DIRECTORY." /><div className="mt-5 divide-y divide-[#eeeae2]">{Object.values(STAFF_DIRECTORY).map((member) => <div key={member.email} className="flex items-center gap-3 py-4"><Avatar member={member} size="md" /><div className="min-w-0 flex-1"><strong className="block text-xs text-[#455267]">{member.name}</strong><p className="mt-1 text-[11px] text-[#89929f]">{member.email}</p></div><span className="rounded-lg bg-[#f2f0ea] px-2.5 py-1.5 text-[10px] font-bold capitalize text-[#697586]">{member.role}</span></div>)}</div></section><section className="rounded-2xl border border-[#e6e2d9] bg-white p-5 sm:p-6"><SectionTitle title="Permission controls" detail="Demo controls show the intended access boundary." /><div className="mt-4 space-y-3">{[['Reporter privacy', 'Reporters only see reports they own', true], ['Moderator tools', 'Moderators can assign, review, and resolve', true], ['Role editing', 'Only administrators can edit staff roles', true], ['Public issue view', 'Known issues are visible without staff access', true]].map(([title, detail, enabled]) => <div key={title as string} className="flex items-center gap-3 rounded-xl bg-[#f7f5f0] p-3"><span className="flex h-7 w-7 items-center justify-center rounded-lg bg-[#e8f6f3] text-[#247c70]"><Check size={14} /></span><div><strong className="block text-xs text-[#536174]">{title as string}</strong><p className="mt-1 text-[10px] text-[#929ba6]">{detail as string}</p></div><span className="ml-auto text-[10px] font-bold text-[#39824b]">{enabled ? 'On' : 'Off'}</span></div>)}</div></section></div><section className="mt-5 rounded-2xl border border-[#d8d2c4] bg-[#fff9e9] p-5 sm:p-6"><div className="flex gap-3"><Gamepad2 size={19} className="mt-0.5 text-[#b7771b]" /><div><h2 className="font-display text-lg font-bold text-[#634c1c]">Future games / configuration</h2><p className="mt-1 max-w-2xl text-xs leading-5 text-[#896f36]">Additional Nulls games can be added later from configuration. Only <strong>Nulls Brawl</strong> is active in this demo; no future game is shown as available for reporting today.</p><button className="mt-4 rounded-xl border border-[#e0c98e] bg-[#fffdf5] px-3 py-2 text-[10px] font-bold text-[#896f36]" data-testid="button-future-game-config">Configuration placeholder</button></div></div></section></div>;
}

function Settings({ pushToast }: { pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  const [digest, setDigest] = useState(true); const [assignments, setAssignments] = useState(true); const [privateNotes, setPrivateNotes] = useState(true);
  return <div className="page-enter"><PageHeading eyebrow="Administrator / Workspace" title="Settings" detail="Tune the staff workspace without changing what players can access." action={<button onClick={() => pushToast('Settings saved', 'Workspace preferences are stored for this local demo.', 'success')} className="flex items-center gap-2 rounded-xl bg-[#2e9f91] px-4 py-2.5 text-xs font-bold text-white" data-testid="button-save-settings"><Check size={15} /> Save changes</button>} /><div className="space-y-5"><section className="rounded-2xl border border-[#e6e2d9] bg-white p-5 sm:p-6"><SectionTitle title="Workspace profile" detail="The administrator identity currently controlling this demo." /><div className="mt-5 flex items-center gap-3"><Avatar member={STAFF_DIRECTORY['mira@nulls.report']} size="md" /><div><strong className="block text-sm text-[#455267]">Mira Sol</strong><span className="text-xs text-[#89929f]">mira@nulls.report · administrator</span></div></div></section><section className="rounded-2xl border border-[#e6e2d9] bg-white p-5 sm:p-6"><SectionTitle title="Staff notifications" detail="Keep the moderation team close to work that needs a response." /><div className="mt-4 divide-y divide-[#eeeae2]">{[['New assignments', 'Notify a staff member when a report is assigned', assignments, setAssignments], ['Daily inbox summary', 'A short summary of report statuses and unresolved work', digest, setDigest], ['Internal note reminders', 'Remind staff when a report note needs a follow-up', privateNotes, setPrivateNotes]].map(([title, detail, value, setter]) => <div key={title as string} className="flex items-center justify-between gap-4 py-4"><div><strong className="block text-xs font-bold text-[#536174]">{title as string}</strong><p className="mt-1 text-[11px] text-[#929ba6]">{detail as string}</p></div><button onClick={() => (setter as (value: boolean) => void)(!(value as boolean))} className={`relative h-6 w-11 shrink-0 rounded-full transition ${value ? 'bg-[#2e9f91]' : 'bg-[#d5d9d8]'}`} data-testid={`button-toggle-${(title as string).toLowerCase().replaceAll(' ', '-')}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white shadow-sm transition ${value ? 'left-6' : 'left-1'}`}></span></button></div>)}</div></section><section className="rounded-2xl border border-[#d8d2c4] bg-[#fff9e9] p-5 sm:p-6"><div className="flex gap-3"><Gamepad2 size={19} className="mt-0.5 text-[#b7771b]" /><div><h2 className="font-display text-lg font-bold text-[#634c1c]">Future games / configuration</h2><p className="mt-1 text-xs leading-5 text-[#896f36]">Additional Nulls games can be added later. Nulls Brawl is the only active game and the only game available in report creation.</p></div></div></section></div></div>;
}

function Login({ signIn, pushToast }: { signIn: (session: Session) => void; pushToast: (title: string, detail?: string, tone?: Toast['tone']) => void }) {
  const [mode, setMode] = useState<'reporter' | 'staff'>('reporter'); const [name, setName] = useState('Alex'); const [email, setEmail] = useState('');
  const accessStaff = (staffEmail: string) => { const member = STAFF_DIRECTORY[staffEmail]; if (member) signIn({ id: member.email, displayName: member.name, email: member.email, role: member.role }); };
  const submitStaff = () => { const member = STAFF_DIRECTORY[email.trim().toLowerCase()]; if (!member) { pushToast('Staff email not found', 'Use one of the configured demo staff identities below.'); return; } accessStaff(member.email); };
  return <div className="min-h-[calc(100dvh-140px)] page-enter"><div className="mx-auto grid max-w-[980px] overflow-hidden rounded-3xl border border-[#e6e2d9] bg-white shadow-[0_14px_40px_rgba(35,53,68,.06)] lg:grid-cols-[.85fr_1.15fr]"><div className="bg-[#202f46] p-7 text-white sm:p-10"><img src="/assets/nulls-logo.png" alt="Nulls" className="h-14 w-14 rounded-2xl" /><p className="mt-10 font-mono text-[10px] uppercase tracking-[.2em] text-[#93a5ba]">Nulls Report</p><h1 className="mt-3 font-display text-3xl font-bold tracking-[-.045em]">A clearer line to the team.</h1><p className="mt-4 text-sm leading-6 text-[#aab8c8]">Submit and follow a Nulls Brawl report, or use the demo staff access to review reports as a moderator.</p><div className="mt-10 space-y-3 text-xs text-[#c7d2de]"><div className="flex items-center gap-2"><CheckCircle2 size={15} className="text-[#70d4bb]" /> Private reporter view</div><div className="flex items-center gap-2"><CheckCircle2 size={15} className="text-[#70d4bb]" /> Clear status updates</div><div className="flex items-center gap-2"><CheckCircle2 size={15} className="text-[#70d4bb]" /> Staff access is demo-only</div></div></div><div className="p-6 sm:p-10"><div className="flex rounded-xl bg-[#f2f0ea] p-1"><button onClick={() => setMode('reporter')} className={`flex-1 rounded-lg py-2.5 text-xs font-bold ${mode === 'reporter' ? 'bg-white text-[#202f46] shadow-sm' : 'text-[#89929f]'}`} data-testid="button-login-reporter">Reporter access</button><button onClick={() => setMode('staff')} className={`flex-1 rounded-lg py-2.5 text-xs font-bold ${mode === 'staff' ? 'bg-white text-[#202f46] shadow-sm' : 'text-[#89929f]'}`} data-testid="button-login-staff">Staff access</button></div>{mode === 'reporter' ? <div className="mt-9"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#ef6358]">Reporter path</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#202f46]">Continue with your report.</h2><p className="mt-3 text-sm leading-6 text-[#7b8693]">No account is required for this demo. Use guest access or add a display name for a more personal report history.</p><label className="mt-7 block text-xs font-bold text-[#536174]">Display name <span className="font-normal text-[#a0a7af]">(optional)</span><input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Alex" className="mt-2 h-11 w-full rounded-xl border border-[#e1ded6] bg-[#fbfaf7] px-3 text-sm outline-none focus:border-[#ef6358]" data-testid="input-reporter-name" /></label><button onClick={() => signIn({ ...CURRENT_REPORTER, displayName: name.trim() || 'Guest reporter' })} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#ef6358] py-3.5 text-xs font-bold text-white" data-testid="button-continue-guest"><UserRound size={15} /> Continue as guest</button><button onClick={() => pushToast('Nulls Connect optional', 'Connect is not wired to a backend in this local demo. Guest access remains available.')} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl border border-[#dedbd3] py-3.5 text-xs font-bold text-[#536174]" data-testid="button-null-connect"><KeyRound size={15} /> Sign in with Nulls Connect <span className="font-normal text-[#a0a7af]">(optional)</span></button><p className="mt-5 text-center text-[10px] leading-4 text-[#a0a7af]">Demo access only. This preview does not provide production authentication.</p></div> : <div className="mt-9"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-[#2e9f91]">Staff path</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#202f46]">Open staff tools.</h2><p className="mt-3 text-sm leading-6 text-[#7b8693]">The source-configured staff directory determines whether this demo opens as a moderator or administrator.</p><label className="mt-7 block text-xs font-bold text-[#536174]">Staff email<input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@nulls.report" className="mt-2 h-11 w-full rounded-xl border border-[#e1ded6] bg-[#fbfaf7] px-3 text-sm outline-none focus:border-[#2e9f91]" data-testid="input-staff-email" /></label><button onClick={submitStaff} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#202f46] py-3.5 text-xs font-bold text-white" data-testid="button-staff-sign-in"><LogIn size={15} /> Enter staff demo</button><div className="mt-7 border-t border-[#eeeae2] pt-5"><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#89929f]">Demo access</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{Object.values(STAFF_DIRECTORY).map((member) => <button key={member.email} onClick={() => accessStaff(member.email)} className="flex items-center gap-2 rounded-xl border border-[#e4e0d7] p-2.5 text-left hover:border-[#2e9f91]" data-testid={`button-demo-${member.role}`}><Avatar member={member} /><span><strong className="block text-[11px] text-[#536174]">{member.name}</strong><span className="block text-[10px] capitalize text-[#929ba6]">{member.role}</span></span></button>)}</div></div><p className="mt-5 text-center text-[10px] leading-4 text-[#a0a7af]">No database, token, or external auth is used in this preview.</p></div>}</div></div></div>;
}

function AccessDenied({ message }: { message: string }) { return <div className="mx-auto max-w-lg py-20 text-center page-enter"><span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#fff0ed] text-[#ca4e44]"><Shield size={24} /></span><h1 className="mt-6 font-display text-2xl font-bold text-[#202f46]">Access restricted</h1><p className="mt-3 text-sm leading-6 text-[#7b8693]">{message}</p><Link href="/" className="mt-7 inline-flex items-center gap-2 rounded-xl bg-[#202f46] px-4 py-3 text-xs font-bold text-white" data-testid="link-access-denied-home">Back to home <ArrowRight size={14} /></Link></div>; }
function EmptyState({ icon: Icon, title, detail, action }: { icon: typeof Search; title: string; detail: string; action?: ReactNode }) { return <div className="flex flex-col items-center justify-center px-6 py-16 text-center"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#f2f0ea] text-[#89929f]"><Icon size={21} /></span><h3 className="mt-4 font-display text-lg font-bold text-[#3a475b]">{title}</h3><p className="mt-2 max-w-sm text-xs leading-5 text-[#89929f]">{detail}</p><div className="mt-4">{action}</div></div>; }
function NotFound() { return <div className="mx-auto max-w-lg py-24 text-center"><img src="/assets/nulls-logo.png" alt="Nulls" className="mx-auto h-16 w-16 rounded-2xl opacity-80" /><h1 className="mt-6 font-display text-3xl font-bold text-[#202f46]">This room does not exist.</h1><p className="mt-3 text-sm text-[#7b8693]">The page may have moved. Let’s get you back to the report workspace.</p><Link href="/" className="mt-7 inline-flex items-center gap-2 rounded-xl bg-[#ef6358] px-4 py-3 text-xs font-bold text-white" data-testid="link-back-home">Back to home <ArrowRight size={14} /></Link></div>; }

function Router() {
  const [location, setLocation] = useLocation();
  const [session, setSession] = useState<Session>(CURRENT_REPORTER);
  const [myReports, setMyReports] = useState(seededMyReports);
  const [inboxReports, setInboxReports] = useState(seededInboxReports);
  const [issues] = useState(seededIssues);
  const [selectedReport, setSelectedReport] = useState<string | undefined>();
  const [toasts, setToasts] = useState<Toast[]>([]);
  const pushToast = (title: string, detail?: string, tone: Toast['tone'] = 'normal') => { if (!title) return; const id = Date.now(); setToasts((items) => [...items, { id, title, detail, tone }]); setTimeout(() => setToasts((items) => items.filter((item) => item.id !== id)), 4200); };
  const signIn = (next: Session) => { setSession(next); setLocation('/'); pushToast('Demo access enabled', `${next.displayName} is signed in as ${next.role}.`, 'success'); };
  const signOut = () => { setSession(CURRENT_REPORTER); setLocation('/login'); pushToast('Signed out', 'The staff demo session has ended.', 'success'); };
  const selectReport = (id: string) => { setSelectedReport(id || undefined); if (id && location !== '/inbox' && session.role !== 'reporter') setLocation('/inbox'); };
  const addReport = (report: Report) => setMyReports((items) => [report, ...items]);
  const privateReports = session.role === 'reporter' ? myReports : [];
  return location === '/login' ? <><Login signIn={signIn} pushToast={pushToast} /><Toasts toasts={toasts} dismiss={(id) => setToasts((items) => items.filter((item) => item.id !== id))} /></> : <AppShell session={session} reports={inboxReports} pushToast={pushToast} signOut={signOut}><Switch><Route path="/"><Overview session={session} reports={session.role === 'reporter' ? privateReports : inboxReports} issues={issues} onSelectReport={selectReport} pushToast={pushToast} /></Route><Route path="/submit">{session.role === 'reporter' ? <Submit session={session} onSubmit={addReport} pushToast={pushToast} /> : <AccessDenied message="Report creation is available from the reporter workspace. Staff accounts use the moderation inbox to review submitted reports." />}</Route><Route path="/my-reports"><MyReports reports={privateReports} session={session} onSelectReport={selectReport} /></Route><Route path="/inbox">{session.role !== 'reporter' ? <InboxPage reports={inboxReports} setReports={setInboxReports} issues={issues} pushToast={pushToast} onSelectReport={selectReport} selectedId={selectedReport} /> : <AccessDenied message="The moderation inbox is restricted to configured moderator and administrator accounts." />}</Route><Route path="/known-issues"><KnownIssues issues={issues} pushToast={pushToast} /></Route><Route path="/administration">{session.role === 'administrator' ? <Administration /> : <AccessDenied message="Administration is available to administrator accounts only." />}</Route><Route path="/settings">{session.role === 'administrator' ? <Settings pushToast={pushToast} /> : <AccessDenied message="Workspace settings are available to administrator accounts only." />}</Route><Route component={NotFound} /></Switch></AppShell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;